<script setup lang="ts">
import { computed, ref, watch, onUnmounted } from 'vue'
import { ArrowRight, ArrowLeft, Quote, BookOpen, Users, Target, Compass, Lightbulb, TrendingUp } from '@lucide/vue'
import { useCmsSection } from '../cms/content'
import { getPage, safeImage } from '../cms/pages'
import { locale } from '../i18n'
import RichTextContent from '../components/RichTextContent.vue'
const props=defineProps<{slug?:string}>()
const c=useCmsSection('CareersPage')
interface Position {slug:string;title:string;department:string;location:string;employmentType:string;description:string;applicationUrl:string}
const jobs=ref<Position[]>([]),loading=ref(true),error=ref(false)
const search=ref(''),department=ref(''),location=ref('')
const active=ref('overview')
const icons=[BookOpen,Users,Target,Compass,Lightbulb,TrendingUp]
const id=computed(()=>locale.value==='id')
const sections=computed(()=>[{key:'overview',label:c.value.overviewTab},{key:'purpose',label:c.value.purposeTab},{key:'benefits',label:c.value.benefitsTab},{key:'positions',label:c.value.positionsTab}])
const departments=computed(()=>[...new Set(jobs.value.map(j=>j.department).filter(Boolean))].sort())
const locations=computed(()=>[...new Set(jobs.value.map(j=>j.location).filter(Boolean))].sort())
const filtered=computed(()=>jobs.value.filter(j=>(!department.value||j.department===department.value)&&(!location.value||j.location===location.value)&&`${j.title} ${j.department} ${j.location}`.toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase())))
const selected=computed(()=>jobs.value.find(j=>j.slug===props.slug))
const application=computed(()=>selected.value?.applicationUrl && /^(https?:\/\/|mailto:)/i.test(selected.value.applicationUrl) && !/[\u0000-\u0020]/.test(selected.value.applicationUrl)?selected.value.applicationUrl:'')
function go(key:string){active.value=key;document.getElementById('career-'+key)?.scrollIntoView?.({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
function reset(){search.value='';department.value='';location.value=''}
let request:AbortController|undefined
async function load(){request?.abort();request=new AbortController();const signal=request.signal;loading.value=true;error.value=false;jobs.value=[];reset();try{const result=await getPage<{data:Position[]}>('website-careers',signal);if(!signal.aborted)jobs.value=Array.isArray(result.data)?result.data:[]}catch{if(!signal.aborted)error.value=true}finally{if(!signal.aborted)loading.value=false}}
watch(locale,load,{immediate:true})
watch([()=>props.slug,()=>selected.value?.title],()=>{document.title=`${selected.value?.title||c.value.heroTitle} | BRIAMCO`})
onUnmounted(()=>request?.abort())
</script>
<template>
<div class="career-page">
  <header class="cr-hero" :style="safeImage(c.heroImage)?{backgroundImage:`linear-gradient(90deg,#071536dd,#07153655),url(${safeImage(c.heroImage)})`}:{}"><div class="ad-wrap"><h1>{{ selected?.title || c.heroTitle }}</h1></div></header>
  <template v-if="slug">
    <section class="ad-wrap cr-job-detail"><RouterLink to="/careers" class="cr-text-link"><ArrowLeft :size="18"/>{{ c.positionsTitle }}</RouterLink><p v-if="loading" role="status">{{ id?'Memuat lowongan…':'Loading position…' }}</p><p v-else-if="error" role="alert">{{ id?'Lowongan tidak dapat dimuat.':'Positions could not be loaded.' }} <button @click="load">{{ id?'Coba lagi':'Try again' }}</button></p><template v-else-if="selected"><div class="cr-job-meta"><span>{{ selected.department }}</span><span>{{ selected.location }}</span><span>{{ selected.employmentType }}</span></div><RichTextContent :content="selected.description"/><a v-if="application" :href="application" class="ad-button">{{ c.applyLabel }}<ArrowRight :size="18"/></a><RouterLink v-else to="/contact" class="ad-button">{{ c.interestLabel }}<ArrowRight :size="18"/></RouterLink></template><p v-else role="alert">{{ id?'Lowongan ini tidak tersedia.':'This position is not available.' }}</p></section>
  </template>
  <template v-else>
    <section id="career-overview" class="ad-wrap cr-overview">
      <div><nav class="cr-section-nav" :aria-label="id?'Navigasi karier':'Careers sections'"><button v-for="s in sections" :key="s.key" :class="{active:active===s.key}" :aria-current="active===s.key?'location':undefined" @click="go(s.key)">{{ s.label }}</button></nav><h2>{{ c.overviewTitle }}</h2><p class="cr-lead">{{ c.overviewLead }}</p><p>{{ c.overviewBody }}</p><p>{{ c.overviewBody2 }}</p><button class="ad-button" @click="go('positions')">{{ c.positionsCta }}<ArrowRight :size="18"/></button></div>
      <aside><div class="cr-culture"><Quote :size="35" aria-hidden="true"/><p class="cr-culture-label">{{ c.cultureLabel }}</p><blockquote>{{ c.cultureQuote }}</blockquote><strong>{{ c.cultureAuthor }}</strong><p>{{ c.cultureRole }}</p></div><button class="cr-text-link" @click="go('positions')">{{ c.positionsCta }}<ArrowRight :size="17"/></button></aside>
    </section>
    <section id="career-purpose" class="cr-purpose"><div class="ad-wrap"><h2>{{ c.purposeTitle }}</h2><p>{{ c.purposeText }}</p></div></section>
    <section class="ad-wrap cr-values cr-space"><h2>{{ c.valuesTitle }}</h2><div class="cr-three-grid"><article v-for="item in c.values" :key="item.title"><h3>{{ item.title }}</h3><p>{{ item.description }}</p></article></div></section>
    <section class="cr-banner" :style="safeImage(c.bannerImage)?{backgroundImage:`linear-gradient(90deg,#071536ee,#07153666),url(${safeImage(c.bannerImage)})`}:{}"><div class="ad-wrap"><h2>{{ c.bannerTitle }}</h2><p>{{ c.bannerBody }}</p><button class="ad-button outline" @click="go('positions')">{{ c.positionsCta }}<ArrowRight :size="18"/></button></div></section>
    <section id="career-benefits" class="cr-benefits cr-space"><div class="ad-wrap"><h2>{{ c.benefitsTitle }}</h2><p class="cr-benefits-intro">{{ c.benefitsIntro }}</p><div class="cr-three-grid"><article v-for="(item,index) in c.benefits" :key="item.title"><component :is="icons[index%icons.length]" :size="44" :stroke-width="1.2" aria-hidden="true"/><h3>{{ item.title }}</h3><p>{{ item.description }}</p></article></div></div></section>
    <section id="career-positions" class="ad-wrap cr-positions cr-space"><h2>{{ c.positionsTitle }}</h2><div class="cr-filters"><label><span class="cr-sr">{{ c.searchPlaceholder }}</span><input v-model="search" type="search" :placeholder="c.searchPlaceholder"/></label><label><span class="cr-sr">{{ c.allSegments }}</span><select v-model="department"><option value="">{{ c.allSegments }}</option><option v-for="d in departments" :key="d">{{ d }}</option></select></label><label><span class="cr-sr">{{ c.allLocations }}</span><select v-model="location"><option value="">{{ c.allLocations }}</option><option v-for="l in locations" :key="l">{{ l }}</option></select></label></div>
      <p v-if="loading" role="status">{{ id?'Memuat lowongan…':'Loading positions…' }}</p><div v-else-if="error" role="alert"><p>{{ id?'Lowongan tidak dapat dimuat. Silakan coba lagi.':'Positions could not be loaded. Please try again.' }}</p><button class="cr-text-link" @click="load">{{ id?'Coba lagi':'Try again' }}</button></div><div v-else-if="!jobs.length" class="cr-empty"><h3>{{ c.emptyTitle }}</h3><p>{{ c.emptyText }}</p><RouterLink class="cr-text-link" to="/contact">{{ c.interestLabel }}<ArrowRight :size="18"/></RouterLink></div><template v-else><p class="cr-result-count" role="status">{{ filtered.length }} {{ id?'lowongan':'positions' }}</p><div v-if="filtered.length" class="cr-three-grid cr-jobs"><RouterLink v-for="job in filtered" :key="job.slug" :to="'/careers/'+encodeURIComponent(job.slug)"><strong>{{ job.department }}</strong><p>{{ job.location }}</p><h3>{{ job.title }}</h3><span>{{ job.employmentType }}</span></RouterLink></div><div v-else class="cr-empty"><p>{{ c.noResults }}</p><button class="cr-text-link" @click="reset">{{ c.resetLabel }}</button></div></template>
    </section>
  </template>
</div>
</template>
<style scoped>
.cr-hero{background-size:cover;background-position:center;background-color:#071536;color:white;padding:120px 0 135px}.cr-hero h1{font-size:clamp(42px,4.7vw,75px);line-height:1.1;letter-spacing:-2px;font-weight:600}.cr-overview{display:grid;grid-template-columns:minmax(0,2.1fr) minmax(250px,1fr);gap:90px;padding-top:80px;padding-bottom:90px}.cr-section-nav{display:flex;gap:26px;border-bottom:1px solid #cbd0dc;margin-bottom:45px;overflow-x:auto}.cr-section-nav button{border:0;border-bottom:2px solid transparent;padding:0 0 14px;color:#73798a;background:none;white-space:nowrap;font-size:14px;cursor:pointer}.cr-section-nav button.active{border-color:#0d80d8;color:#0d80d8;font-weight:600}.cr-overview h2{font-size:clamp(30px,3.1vw,47px);line-height:1.2;letter-spacing:-1.4px;margin-bottom:40px}.cr-overview p{font-size:16px;line-height:1.7;color:#566178;margin-bottom:20px}.cr-overview .cr-lead{font-family:Georgia,serif;font-size:clamp(24px,2.2vw,33px);line-height:1.25;font-weight:700;background:linear-gradient(110deg,#0784d7,#6453ee);background-clip:text;-webkit-text-fill-color:transparent;margin-bottom:26px}.cr-overview .ad-button{margin-top:10px;font-size:16px}.cr-culture{padding:30px;background:linear-gradient(120deg,#e5f1fc,#efedff);border-top:3px solid #0d80d8;border-radius:0 0 35px 0}.cr-culture>svg{color:#0d80d8;margin-bottom:15px}.cr-culture .cr-culture-label{font-size:12px;text-transform:uppercase;letter-spacing:1px;color:#0d80d8;margin-bottom:15px}.cr-culture blockquote{font-family:Georgia,serif;font-size:24px;line-height:1.3;font-weight:700;margin-bottom:25px}.cr-culture strong{font-size:14px}.cr-culture>p:last-child{font-size:13px;margin:5px 0 0}.cr-text-link{display:inline-flex;align-items:center;gap:12px;border:0;background:none;color:#0d80d8;font:inherit;font-size:15px;font-weight:600;padding:0;margin-top:20px;cursor:pointer}.cr-text-link:hover{text-decoration:underline}.cr-purpose{text-align:center;padding:80px 0 95px;background:linear-gradient(110deg,#e5f1fc,#efedff)}.cr-purpose h2{font-size:32px;margin-bottom:50px;letter-spacing:-1px}.cr-purpose p{font-family:Georgia,serif;font-size:clamp(30px,3.2vw,49px);line-height:1.3;font-weight:bold;max-width:900px;margin:auto;color:#145cbe}.cr-space{padding-top:80px;padding-bottom:90px}.cr-space h2{font-size:34px;color:#0d80d8;letter-spacing:-1px;margin-bottom:45px}.cr-three-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:45px 40px}.cr-values article{border-top:2px solid #e0e4eb;padding-top:25px}.cr-three-grid h3{font-size:23px;line-height:1.25;letter-spacing:-.7px;margin-bottom:12px}.cr-three-grid p{font-size:15px;line-height:1.65;color:#566178}.cr-banner{background-color:#071536;background-size:cover;background-position:center;color:white;padding:75px 0}.cr-banner h2{font-family:Georgia,serif;font-size:clamp(34px,3.5vw,55px);line-height:1.1;max-width:800px;margin-bottom:25px}.cr-banner p{font-size:19px;line-height:1.6;max-width:800px;margin-bottom:30px}.cr-banner .ad-button{color:white;font-size:16px}.cr-benefits{background:linear-gradient(110deg,#e5f1fc,#efedff)}.cr-benefits h2{margin-bottom:20px}.cr-benefits-intro{font-size:18px;color:#566178;margin-bottom:45px}.cr-benefits article{background:white;border-top:3px solid #0d80d8;border-radius:0 0 30px 0;padding:35px;min-height:280px}.cr-benefits article>svg{margin-bottom:25px;color:#0d80d8}.cr-filters{display:grid;grid-template-columns:2fr 1fr 1fr;gap:40px;margin-bottom:40px}.cr-filters input,.cr-filters select{width:100%;font:inherit;font-size:14px;color:#566178;border:0;border-bottom:1px solid #9da8bd;border-radius:0;background:white;padding:12px 0}.cr-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.cr-jobs>a{padding:25px;border:1px solid #cbd0dc;min-height:190px;transition:border-color .2s}.cr-jobs>a:hover{border-color:#0d80d8}.cr-jobs strong{font-size:13px}.cr-jobs p{font-size:13px;margin-bottom:16px}.cr-jobs h3{font-size:20px;color:#0d80d8}.cr-jobs span{font-size:12px;color:#566178}.cr-result-count{font-size:13px;color:#566178;margin-bottom:20px}.cr-empty{border:1px solid #dde3ee;padding:35px}.cr-empty h3{font-size:24px;margin-bottom:12px}.cr-empty p{color:#566178;line-height:1.6}.cr-job-detail{padding:50px 0 90px;max-width:1000px}.cr-job-meta{display:flex;flex-wrap:wrap;gap:25px;color:#566178;font-size:15px;margin:25px 0 40px}.cr-job-detail .ad-button{margin-top:25px}[id^=career-]{scroll-margin-top:30px}@media(max-width:1000px){.cr-overview{gap:40px}.cr-three-grid{gap:30px}.cr-benefits article{padding:25px}.cr-section-nav{gap:20px}}@media(max-width:720px){.cr-hero{padding:80px 0}.cr-hero h1{letter-spacing:-1px}.cr-overview{grid-template-columns:1fr;gap:40px;padding:45px 0 55px}.cr-section-nav{margin-bottom:30px}.cr-overview h2{margin-bottom:25px}.cr-three-grid{grid-template-columns:1fr;gap:30px}.cr-space{padding:55px 0}.cr-purpose{padding:55px 0 65px}.cr-purpose h2{margin-bottom:30px}.cr-space h2{font-size:30px;margin-bottom:30px}.cr-banner{padding:55px 0}.cr-banner p{font-size:17px}.cr-filters{grid-template-columns:1fr;gap:15px}.cr-benefits article{min-height:220px}.cr-jobs>a{min-height:160px}}
</style>
